Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="apertureState">Opening: No opening (a)</button>
<label style="flex-direction:row;align-items:center;gap:6px">
  <input id="rayComparison" type="checkbox">
  Side-by-side ray comparison
</label>
<button id="resetPinhole">Reset pinhole</button>
<div id="stepTitle" style="font-weight:bold;margin-top:4px">No opening: no image</div>
<div id="stepNarration" style="font-size:11px;line-height:1.25;max-width:260px">
  Several green and brown rays from different parts of the tree land on the same wall points.
</div>
<div style="display:flex;gap:4px;margin-top:3px">
  <button id="prevStep">◀</button>
  <button id="nextStep">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// wall panel        → custom YZ Plane + Cylinder outline, white fill, thick black edges
// wall sample marks → RingGeometry on wall plane, yellow/red outlines
// tree trunk        → ShapeGeometry tapered brown trunk billboard
// branches          → Cylinders, brown, reaching into canopy
// canopy lobes      → CircleGeometry billboards, layered greens
// no-aperture rays  → Cylinder ray shafts + Cone arrowheads, green/brown, many-to-one bundles
// pinhole barrier   → BoxGeometry black slab with dark side faces
// pinhole aperture  → white CircleGeometry on barrier face, draggable
// pinhole rays      → segmented Cylinder rays S→P→I with Cone arrowheads
// rejected rays     → faint transparent direct rays blocked by barrier
// projected image   → translucent pale CircleGeometry/ShapeGeometry on wall plane, inverted
// labels            → addLabel: Wall, Pinhole, (a), (b)

const wallX = -4.5;
const wallY0 = -2.8, wallY1 = 3.0;
const wallZ0 = 0.0, wallZ1 = 2.0;
const brown = 0x7b461e;
const greenRay = 0x20d600;
const darkGreen = 0x159600;
const brightGreen = 0x37ff00;
const paleGreen = 0xa7ff7d;
const paleBrown = 0xc1a58f;

const pinhole = new THREE.Vector3(-0.35, -0.55, 0.95);
const defaultPinhole = pinhole.clone();
const wallTargets = [
  new THREE.Vector3(wallX, 0.45, 0.9),
  new THREE.Vector3(wallX, -1.75, 0.75)
];
let selectedWallIndex = 0;
let apertureMode = 'No opening (a)';
let comparisonMode = false;
let currentStep = 0;

const scenePoints = [
  { name: 'top foliage', p: new THREE.Vector3(3.10, 1.75, 0.80), color: greenRay, type: 'leaf' },
  { name: 'left foliage', p: new THREE.Vector3(2.25, 0.15, 0.80), color: greenRay, type: 'leaf' },
  { name: 'right foliage', p: new THREE.Vector3(4.10, 0.05, 0.85), color: greenRay, type: 'leaf' },
  { name: 'lower foliage', p: new THREE.Vector3(3.05, -0.65, 0.80), color: greenRay, type: 'leaf' },
  { name: 'branch', p: new THREE.Vector3(2.70, -0.15, 0.82), color: brown, type: 'wood' },
  { name: 'trunk', p: new THREE.Vector3(3.20, -1.80, 0.80), color: brown, type: 'wood' }
];

const materialCache = new Map();
function mat(color, opts = {}) {
  const key = `${color}_${opts.opacity ?? 1}_${opts.transparent ?? false}_${opts.side ?? 0}_${opts.depthWrite ?? true}`;
  if (!materialCache.has(key)) {
    materialCache.set(key, new THREE.MeshBasicMaterial({
      color,
      transparent: opts.transparent || (opts.opacity != null && opts.opacity < 1),
      opacity: opts.opacity ?? 1,
      side: opts.side ?? THREE.FrontSide,
      depthWrite: opts.depthWrite ?? true
    }));
  }
  return materialCache.get(key);
}

function cylinderBetween(a, b, radius, color, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 12, 1);
  const mesh = new THREE.Mesh(geom, mat(color, { opacity, transparent: opacity < 1, depthWrite: opacity >= 1 }));
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function coneArrow(tip, dir, color, opacity = 1, radius = 0.07, length = 0.18) {
  const geom = new THREE.ConeGeometry(radius, length, 18);
  const mesh = new THREE.Mesh(geom, mat(color, { opacity, transparent: opacity < 1, depthWrite: opacity >= 1 }));
  mesh.position.copy(tip).addScaledVector(dir, -length / 2);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}

function addRay(group, a, b, color, opts = {}) {
  const opacity = opts.opacity ?? 1;
  const radius = opts.radius ?? 0.013;
  group.add(cylinderBetween(a, b, radius, color, opacity));
  if (opts.arrow !== false) {
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const tip = opts.tip ? opts.tip.clone() : b.clone().addScaledVector(dir, -0.08);
    group.add(coneArrow(tip, dir, color, opacity, opts.arrowRadius ?? 0.06, opts.arrowLength ?? 0.17));
  }
}

function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse?.(o => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    });
  }
}

function wallIntersectionFromScenePoint(S, P = pinhole) {
  const u = (P.x - wallX) / (S.x - P.x);
  return P.clone().add(new THREE.Vector3().subVectors(P, S).multiplyScalar(u));
}

function projectedRadius(S, r, P = pinhole) {
  return r * Math.abs((P.x - wallX) / (S.x - P.x));
}

function makeCircleXY(radius, color, opacity = 1) {
  return new THREE.Mesh(
    new THREE.CircleGeometry(radius, 48),
    mat(color, { opacity, transparent: opacity < 1, side: THREE.DoubleSide, depthWrite: opacity >= 1 })
  );
}

function makeWallCircleYZ(radius, color, opacity = 1) {
  const m = makeCircleXY(radius, color, opacity);
  m.rotation.y = Math.PI / 2;
  return m;
}

function makeRingYZ(radius, color) {
  const m = new THREE.Mesh(
    new THREE.RingGeometry(radius * 0.72, radius, 32),
    mat(color, { side: THREE.DoubleSide })
  );
  m.rotation.y = Math.PI / 2;
  return m;
}

function makeWall() {
  const g = new THREE.Group();
  const verts = new Float32Array([
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ0, wallX, wallY1, wallZ1,
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ1, wallX, wallY0, wallZ1
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.computeVertexNormals();
  const plane = new THREE.Mesh(geom, mat(0xffffff, { side: THREE.DoubleSide }));
  g.add(plane);

  const edges = [
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ0)],
    [new THREE.Vector3(wallX, wallY0, wallZ1), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY1, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY0, wallZ1)]
  ];
  edges.forEach(([a, b]) => g.add(cylinderBetween(a, b, 0.026, 0x000000)));
  return g;
}

function makeTree() {
  const g = new THREE.Group();

  const trunkShape = new THREE.Shape();
  trunkShape.moveTo(2.72, -2.62);
  trunkShape.bezierCurveTo(2.86, -2.42, 2.98, -2.0, 3.02, -1.25);
  trunkShape.lineTo(3.11, 0.10);
  trunkShape.lineTo(3.38, 0.10);
  trunkShape.bezierCurveTo(3.34, -0.75, 3.43, -1.75, 3.65, -2.62);
  trunkShape.bezierCurveTo(3.42, -2.72, 2.95, -2.72, 2.72, -2.62);
  const trunk = new THREE.Mesh(new THREE.ShapeGeometry(trunkShape), mat(brown, { side: THREE.DoubleSide }));
  trunk.position.z = 0.80;
  g.add(trunk);

  const branchPairs = [
    [new THREE.Vector3(3.16, -0.25, 0.80), new THREE.Vector3(2.30, 0.55, 0.80)],
    [new THREE.Vector3(3.23, -0.05, 0.80), new THREE.Vector3(3.95, 0.55, 0.84)],
    [new THREE.Vector3(3.14, -0.85, 0.80), new THREE.Vector3(2.45, -0.30, 0.80)],
    [new THREE.Vector3(3.32, -0.75, 0.80), new THREE.Vector3(4.15, -0.05, 0.84)]
  ];
  branchPairs.forEach(([a, b]) => g.add(cylinderBetween(a, b, 0.08, brown)));

  const lobes = [
    { c: [3.00, 1.25, 0.92], r: 1.45, col: darkGreen },
    { c: [3.25, 0.65, 0.80], r: 1.35, col: brightGreen },
    { c: [2.35, 0.05, 0.78], r: 1.00, col: brightGreen },
    { c: [4.05, 0.10, 0.86], r: 1.00, col: brightGreen },
    { c: [3.05, -0.25, 0.76], r: 0.95, col: brightGreen }
  ];
  lobes.forEach(l => {
    const m = makeCircleXY(l.r, l.col);
    m.position.set(l.c[0], l.c[1], l.c[2]);
    g.add(m);
  });

  scenePoints.forEach(sp => {
    const dot = makeCircleXY(0.055, sp.type === 'leaf' ? 0x0a8f00 : brown);
    dot.position.copy(sp.p).add(new THREE.Vector3(0, 0, -0.015));
    g.add(dot);
  });

  return g;
}

function makeBarrier() {
  const g = new THREE.Group();
  const box = new THREE.Mesh(new THREE.BoxGeometry(0.18, 5.5, 1.8), mat(0x000000));
  box.position.set(-0.35, 0.25, 1.0);
  g.add(box);
  const edge = new THREE.Mesh(new THREE.BoxGeometry(0.025, 5.5, 0.04), mat(0x151515));
  edge.position.set(-0.45, 0.25, 1.92);
  g.add(edge);
  return g;
}

function addNoApertureRays(panel, onlySelected = false) {
  const targets = onlySelected ? [wallTargets[selectedWallIndex]] : wallTargets;
  targets.forEach((W, wi) => {
    scenePoints.forEach((sp, idx) => {
      const start = sp.p.clone();
      const end = W.clone();
      const jitter = (idx - 2.5) * 0.006;
      start.z += jitter;
      end.y += onlySelected ? 0 : (idx - 2.5) * 0.012;
      addRay(panel.rayGroup, start, end, sp.color, { radius: 0.012, arrowRadius: 0.055, arrowLength: 0.16 });
    });
  });
}

function addPinholeRays(panel) {
  scenePoints.forEach(sp => {
    const I = wallIntersectionFromScenePoint(sp.p);
    addRay(panel.rayGroup, sp.p, pinhole, sp.color, { radius: 0.012, arrow: false });
    addRay(panel.rayGroup, pinhole, I, sp.color, { radius: 0.012, arrowRadius: 0.055, arrowLength: 0.16 });
  });

  const W = wallTargets[selectedWallIndex];
  scenePoints.forEach(sp => {
    addRay(panel.rejectedGroup, sp.p, W, sp.type === 'leaf' ? 0x20d600 : brown, {
      opacity: 0.14, radius: 0.008, arrow: false
    });
  });

  const nearest = nearestProjectedScenePoint(W);
  if (nearest) {
    const I = wallIntersectionFromScenePoint(nearest.p);
    addRay(panel.highlightGroup, nearest.p, pinhole, 0xffff00, { radius: 0.022, arrow: false });
    addRay(panel.highlightGroup, pinhole, I, 0xffff00, { radius: 0.022, arrowRadius: 0.075, arrowLength: 0.20 });
  }
}

function addProjectedImage(panel) {
  const lobes = [
    { c: new THREE.Vector3(3.00, 1.25, 0.92), r: 1.45, col: paleGreen },
    { c: new THREE.Vector3(3.25, 0.65, 0.80), r: 1.35, col: paleGreen },
    { c: new THREE.Vector3(2.35, 0.05, 0.78), r: 1.00, col: paleGreen },
    { c: new THREE.Vector3(4.05, 0.10, 0.86), r: 1.00, col: paleGreen },
    { c: new THREE.Vector3(3.05, -0.25, 0.76), r: 0.95, col: paleGreen }
  ];
  lobes.forEach(l => {
    const I = wallIntersectionFromScenePoint(l.c);
    const m = makeWallCircleYZ(projectedRadius(l.c, l.r) * 0.52, l.col, 0.55);
    m.position.copy(I).add(new THREE.Vector3(0.018, 0, 0));
    panel.imageGroup.add(m);
  });

  const trunkPts = [
    new THREE.Vector3(3.1, -2.2, 0.8),
    new THREE.Vector3(3.15, -1.1, 0.8),
    new THREE.Vector3(3.24, 0.0, 0.8)
  ].map(p => wallIntersectionFromScenePoint(p));

  const shape = new THREE.Shape();
  shape.moveTo(trunkPts[0].z - 0.12, trunkPts[0].y);
  shape.lineTo(trunkPts[1].z - 0.07, trunkPts[1].y);
  shape.lineTo(trunkPts[2].z - 0.04, trunkPts[2].y);
  shape.lineTo(trunkPts[2].z + 0.06, trunkPts[2].y);
  shape.lineTo(trunkPts[1].z + 0.10, trunkPts[1].y);
  shape.lineTo(trunkPts[0].z + 0.18, trunkPts[0].y);
  shape.closePath();
  const trunkImg = new THREE.Mesh(new THREE.ShapeGeometry(shape), mat(paleBrown, { opacity: 0.58, transparent: true, side: THREE.DoubleSide, depthWrite: false }));
  trunkImg.rotation.y = Math.PI / 2;
  trunkImg.position.x = wallX + 0.022;
  panel.imageGroup.add(trunkImg);

  const branchA = wallIntersectionFromScenePoint(new THREE.Vector3(2.45, -0.30, 0.80));
  const branchB = wallIntersectionFromScenePoint(new THREE.Vector3(4.10, 0.35, 0.84));
  const branchC = wallIntersectionFromScenePoint(new THREE.Vector3(3.18, -0.15, 0.80));
  panel.imageGroup.add(cylinderBetween(branchC.clone().setX(wallX + 0.03), branchA.clone().setX(wallX + 0.03), 0.035, paleBrown, 0.55));
  panel.imageGroup.add(cylinderBetween(branchC.clone().setX(wallX + 0.03), branchB.clone().setX(wallX + 0.03), 0.035, paleBrown, 0.55));
}

function nearestProjectedScenePoint(W) {
  let best = null, bestD = Infinity;
  scenePoints.forEach(sp => {
    const I = wallIntersectionFromScenePoint(sp.p);
    const d2 = (I.y - W.y) ** 2 + (I.z - W.z) ** 2;
    if (d2 < bestD) { bestD = d2; best = sp; }
  });
  return best;
}

function makePanel(kind) {
  const root = new THREE.Group();
  root.add(makeWall());
  root.add(makeTree());

  const sampleGroup = new THREE.Group();
  root.add(sampleGroup);
  wallTargets.forEach((W, i) => {
    const r = makeRingYZ(i === selectedWallIndex ? 0.13 : 0.10, i === selectedWallIndex ? 0xff0000 : 0xffc400);
    r.position.copy(W).add(new THREE.Vector3(0.035, 0, 0));
    r.userData.sampleIndex = i;
    registerInteractive(r, {
      title: `Wall sample ${i + 1}`,
      tooltip: 'Click this wall point',
      body: 'This selected wall position is used to compare many mixed incoming directions with the single ray admitted by a pinhole.',
      onClick: () => { selectedWallIndex = i; rebuildAllPanels(); updateState(false); }
    });
    sampleGroup.add(r);
  });

  const barrierGroup = makeBarrier();
  root.add(barrierGroup);

  const pinholeMesh = makeWallCircleYZ(0.13, 0xffffff, 1);
  pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.095, 0, 0));
  registerInteractive(pinholeMesh, {
    title: 'Pinhole aperture',
    tooltip: 'Drag the pinhole',
    body: 'Moving the pinhole changes which straight-line paths survive and shifts the projected image on the wall.'
  });
  root.add(pinholeMesh);

  const imageGroup = new THREE.Group();
  const rejectedGroup = new THREE.Group();
  const rayGroup = new THREE.Group();
  const highlightGroup = new THREE.Group();
  root.add(imageGroup, rejectedGroup, rayGroup, highlightGroup);

  const panel = { root, kind, sampleGroup, barrierGroup, pinholeMesh, imageGroup, rejectedGroup, rayGroup, highlightGroup };
  updatePanelKind(panel, kind);
  return panel;
}

function updatePanelKind(panel, kind) {
  panel.kind = kind;
  panel.barrierGroup.visible = kind === 'pin';
  panel.pinholeMesh.visible = kind === 'pin';
  panel.imageGroup.visible = kind === 'pin';
  panel.rejectedGroup.visible = kind === 'pin';
  clearGroup(panel.rayGroup);
  clearGroup(panel.imageGroup);
  clearGroup(panel.rejectedGroup);
  clearGroup(panel.highlightGroup);
  if (kind === 'no') addNoApertureRays(panel, comparisonMode);
  else {
    addPinholeRays(panel);
    addProjectedImage(panel);
  }
  panel.pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.095, 0, 0));
  panel.sampleGroup.children.forEach((r, i) => {
