    state: { apertureState: 'Pinhole opening (b)', rayComparison: false }
  },
  {
    title: 'Compare one wall point',
    narration: 'In the comparison view, the same highlighted wall point is shown in both cases. Without the aperture it mixes many directions; with the pinhole only one dominant ray reaches it.',
    state: { apertureState: 'Pinhole opening (b)', rayComparison: true }
  }
];

function goToStep(i) {
  currentStep = (i + steps.length) % steps.length;
  const s = steps[currentStep];
  apertureMode = s.state.apertureState;
  document.getElementById('rayComparison').checked = s.state.rayComparison;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarration').textContent = s.narration;
  updateState(true);
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(currentStep + 1));

let draggingPinhole = false;
let lastDrag = new THREE.Vector2();
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();

function pointerNDC(e) {
  const r = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPointer.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', e => {
  if (apertureMode !== 'Pinhole opening (b)' && !comparisonMode) return;
  pointerNDC(e);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const objects = comparisonMode ? [compareRight.pinholeMesh] : [mainPanel.pinholeMesh];
  const hits = dragRaycaster.intersectObjects(objects, true);
  if (hits.length) {
    draggingPinhole = true;
    lastDrag.set(e.clientX, e.clientY);
    controls.enabled = false;
    canvas.setPointerCapture?.(e.pointerId);
    showTooltip('Drag to move the pinhole aperture', e);
  }
});

canvas.addEventListener('pointermove', e => {
  if (!draggingPinhole) return;
  const dx = e.clientX - lastDrag.x;
  const dy = e.clientY - lastDrag.y;
  lastDrag.set(e.clientX, e.clientY);

  const scale = 1 / Math.max(camera.zoom || 1, 0.2);
  pinhole.y = THREE.MathUtils.clamp(pinhole.y - dy * 0.010 * scale, -2.20, 2.55);
  pinhole.z = THREE.MathUtils.clamp(pinhole.z + dx * 0.008 * scale, 0.25, 1.75);

  rebuildAllPanels();
  updateState(false);
  showTooltip('Moving aperture shifts the inverted projection', e);
});

window.addEventListener('pointerup', e => {
  if (!draggingPinhole) return;
  draggingPinhole = false;
  controls.enabled = true;
  canvas.releasePointerCapture?.(e.pointerId);
  hideTooltip();
});

goToStep(0);
