</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// wall panel             → BufferGeometry YZ rectangle at X=-4.5, white fill, thick black CylinderGeometry outline
// wall sample locations  → small RingGeometry markers on wall plane, red selected/yellow alternate
// tree trunk             → tapered ShapeGeometry billboard, brown #7b461e
// tree branches          → thick CylinderGeometry strokes, brown #7b461e
// canopy lobes           → overlapping CircleGeometry billboards, dark/bright greens
// ray bundles panel (a)  → dense CylinderGeometry rays + ConeGeometry arrowheads converging to two wall points
// barrier panel (b)      → BoxGeometry black oblique cuboid with dark side face
// pinhole                → white CircleGeometry disk on barrier face, draggable
// allowed pinhole rays   → CylinderGeometry segments S→P and P→wall intersection with arrowheads
// rejected rays          → transparent dim direct CylinderGeometry rays blocked by the barrier
// projected image        → translucent pale green wall disks and pale brown wall trunk/branches, inverted
// labels                 → addLabel: Wall, Pinhole, (a), (b)

setUiLayout('bottom', 172);

const wallX = -4.5;
const wallY0 = -2.8, wallY1 = 3.0;
const wallZ0 = 0.0, wallZ1 = 2.0;
const brown = 0x7b461e;
const greenRay = 0x20d600;
const darkGreen = 0x159600;
const brightGreen = 0x37ff00;
const paleGreen = 0xa7ff7d;
const paleBrown = 0xc1a58f;

const pinhole = new THREE.Vector3(-0.35, -0.55, 0.95);
const defaultPinhole = pinhole.clone();
const wallTargets = [
  new THREE.Vector3(wallX, 0.45, 0.90),
  new THREE.Vector3(wallX, -1.75, 0.75)
];

let selectedWallIndex = 0;
let apertureMode = 'No opening (a)';
let comparisonMode = true;
let currentStep = 0;

const scenePoints = [
  { name: 'top foliage',    p: new THREE.Vector3(3.05, 1.78, 0.90), color: greenRay, type: 'leaf' },
  { name: 'upper foliage',  p: new THREE.Vector3(3.85, 0.95, 0.86), color: greenRay, type: 'leaf' },
  { name: 'left foliage',   p: new THREE.Vector3(2.25, 0.15, 0.80), color: greenRay, type: 'leaf' },
  { name: 'right foliage',  p: new THREE.Vector3(4.20, 0.02, 0.86), color: greenRay, type: 'leaf' },
  { name: 'lower foliage',  p: new THREE.Vector3(3.00, -0.62, 0.78), color: greenRay, type: 'leaf' },
  { name: 'left branch',    p: new THREE.Vector3(2.58, -0.22, 0.82), color: brown, type: 'wood' },
  { name: 'trunk middle',   p: new THREE.Vector3(3.20, -1.45, 0.80), color: brown, type: 'wood' },
  { name: 'trunk bottom',   p: new THREE.Vector3(3.28, -2.35, 0.80), color: brown, type: 'wood' }
];

const mats = new Map();
function mat(color, opts = {}) {
  const key = `${color}_${opts.opacity ?? 1}_${opts.side ?? THREE.FrontSide}_${opts.depthWrite ?? true}`;
  if (!mats.has(key)) {
    mats.set(key, new THREE.MeshBasicMaterial({
      color,
      transparent: (opts.opacity ?? 1) < 1,
      opacity: opts.opacity ?? 1,
      side: opts.side ?? THREE.FrontSide,
      depthWrite: opts.depthWrite ?? true
    }));
  }
  return mats.get(key);
}

function cylinderBetween(a, b, radius, color, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-6);
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 12, 1),
    mat(color, { opacity, depthWrite: opacity >= 0.95 })
  );
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function coneArrow(tip, dir, color, opacity = 1, radius = 0.055, length = 0.17) {
  const mesh = new THREE.Mesh(
    new THREE.ConeGeometry(radius, length, 16),
    mat(color, { opacity, depthWrite: opacity >= 0.95 })
  );
  mesh.position.copy(tip).addScaledVector(dir.clone().normalize(), -length / 2);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}

function addRay(group, a, b, color, opts = {}) {
  const opacity = opts.opacity ?? 1;
  const radius = opts.radius ?? 0.016;
  group.add(cylinderBetween(a, b, radius, color, opacity));
  if (opts.arrow !== false) {
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const t = opts.arrowT ?? 0.94;
    const tip = a.clone().lerp(b, t);
    group.add(coneArrow(tip, dir, color, opacity, opts.arrowRadius ?? 0.060, opts.arrowLength ?? 0.18));
  }
}

function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse?.(o => {
      o.geometry?.dispose?.();
    });
  }
}

function wallIntersectionFromScenePoint(S, P = pinhole) {
  const u = (P.x - wallX) / (S.x - P.x);
  return P.clone().add(new THREE.Vector3().subVectors(P, S).multiplyScalar(u));
}

function projectedRadius(S, r, P = pinhole) {
  return r * Math.abs((P.x - wallX) / (S.x - P.x));
}

function makeCircleXY(radius, color, opacity = 1) {
  return new THREE.Mesh(
    new THREE.CircleGeometry(radius, 64),
    mat(color, { opacity, side: THREE.DoubleSide, depthWrite: opacity >= 0.95 })
  );
}

function makeWallCircleYZ(radius, color, opacity = 1) {
  const m = makeCircleXY(radius, color, opacity);
  m.rotation.y = Math.PI / 2;
  return m;
}

function makeWallRingYZ(radius, color) {
  const m = new THREE.Mesh(
    new THREE.RingGeometry(radius * 0.68, radius, 36),
    mat(color, { side: THREE.DoubleSide })
  );
  m.rotation.y = Math.PI / 2;
  return m;
}

function makeWall() {
  const g = new THREE.Group();
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ0, wallX, wallY1, wallZ1,
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ1, wallX, wallY0, wallZ1
  ]), 3));
  geom.computeVertexNormals();
  g.add(new THREE.Mesh(geom, mat(0xffffff, { side: THREE.DoubleSide })));

  const edges = [
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ0)],
    [new THREE.Vector3(wallX, wallY0, wallZ1), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY1, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY0, wallZ1)]
  ];
  edges.forEach(([a, b]) => g.add(cylinderBetween(a, b, 0.032, 0x000000)));
  return g;
}

function makeTree() {
  const g = new THREE.Group();

  const trunkShape = new THREE.Shape();
  trunkShape.moveTo(2.73, -2.62);
  trunkShape.bezierCurveTo(2.92, -2.44, 3.02, -1.85, 3.05, -0.85);
  trunkShape.lineTo(3.10, 0.12);
  trunkShape.lineTo(3.39, 0.12);
  trunkShape.bezierCurveTo(3.35, -0.82, 3.45, -1.84, 3.67, -2.62);
  trunkShape.bezierCurveTo(3.45, -2.72, 2.95, -2.72, 2.73, -2.62);
  const trunk = new THREE.Mesh(new THREE.ShapeGeometry(trunkShape), mat(brown, { side: THREE.DoubleSide }));
  trunk.position.z = 0.80;
  g.add(trunk);

  [
    [new THREE.Vector3(3.17, -0.20, 0.80), new THREE.Vector3(2.24, 0.58, 0.80), 0.075],
    [new THREE.Vector3(3.25, -0.05, 0.80), new THREE.Vector3(4.06, 0.62, 0.84), 0.080],
    [new THREE.Vector3(3.14, -0.82, 0.80), new THREE.Vector3(2.38, -0.24, 0.80), 0.060],
    [new THREE.Vector3(3.32, -0.72, 0.80), new THREE.Vector3(4.22, -0.02, 0.84), 0.060]
  ].forEach(([a, b, r]) => g.add(cylinderBetween(a, b, r, brown)));

  [
    { c: [3.00, 1.25, 0.92], r: 1.45, col: darkGreen },
    { c: [3.25, 0.65, 0.80], r: 1.35, col: brightGreen },
    { c: [2.35, 0.05, 0.78], r: 1.00, col: brightGreen },
    { c: [4.05, 0.10, 0.86], r: 1.00, col: brightGreen },
    { c: [3.05, -0.25, 0.76], r: 0.95, col: brightGreen }
  ].forEach(l => {
    const m = makeCircleXY(l.r, l.col);
    m.position.set(l.c[0], l.c[1], l.c[2]);
    g.add(m);
  });

  scenePoints.forEach(sp => {
    const d = makeCircleXY(0.045, sp.type === 'leaf' ? 0x118f00 : brown);
    d.position.copy(sp.p).add(new THREE.Vector3(0, 0, 0.025));
    g.add(d);
  });

  return g;
}

function makeBarrier() {
  const g = new THREE.Group();
  const slab = new THREE.Mesh(new THREE.BoxGeometry(0.18, 5.50, 1.80), mat(0x000000));
  slab.position.set(-0.35, 0.25, 1.00);
  g.add(slab);
  const side = new THREE.Mesh(new THREE.BoxGeometry(0.035, 5.50, 0.045), mat(0x151515));
  side.position.set(-0.46, 0.25, 1.91);
  g.add(side);
  return g;
}

function nearestProjectedScenePoint(W) {
  let best = null, bestD = Infinity;
  scenePoints.forEach(sp => {
    const I = wallIntersectionFromScenePoint(sp.p);
    const d2 = (I.y - W.y) ** 2 + (I.z - W.z) ** 2;
    if (d2 < bestD) {
      bestD = d2;
      best = sp;
    }
  });
  return best;
}

function addNoApertureRays(panel, onlySelected = false) {
  const targets = onlySelected ? [wallTargets[selectedWallIndex]] : wallTargets;
  targets.forEach((W, wi) => {
    scenePoints.forEach((sp, idx) => {
      const a = sp.p.clone();
      const b = W.clone();
      a.z += (idx - 3.5) * 0.010;
      b.y += onlySelected ? 0 : (idx - 3.5) * 0.010;
      b.z += onlySelected ? 0 : (wi === 0 ? 0.006 : -0.006) * (idx - 3.5);
      addRay(panel.rayGroup, a, b, sp.color, {
        radius: 0.014,
        arrowRadius: 0.060,
        arrowLength: 0.18,
        arrowT: 0.965
      });
    });
  });
}

function addPinholeRays(panel) {
  scenePoints.forEach(sp => {
    const I = wallIntersectionFromScenePoint(sp.p);
    addRay(panel.rayGroup, sp.p, pinhole, sp.color, { radius: 0.014, arrow: false });
    addRay(panel.rayGroup, pinhole, I, sp.color, {
      radius: 0.014,
      arrowRadius: 0.060,
      arrowLength: 0.18,
      arrowT: 0.95
    });
  });

  const W = wallTargets[selectedWallIndex];
  scenePoints.forEach(sp => {
    addRay(panel.rejectedGroup, sp.p, W, sp.type === 'leaf' ? greenRay : brown, {
      opacity: 0.16,
      radius: 0.009,
      arrow: false
    });
  });

  const match = nearestProjectedScenePoint(W);
  if (match) {
    const I = wallIntersectionFromScenePoint(match.p);
    addRay(panel.focusGroup, match.p, pinhole, match.color, { radius: 0.021, arrow: false });
    addRay(panel.focusGroup, pinhole, I, match.color, {
      radius: 0.021,
      arrowRadius: 0.072,
      arrowLength: 0.20,
      arrowT: 0.95
    });
  }
}

function addProjectedImage(panel) {
  [
    { c: new THREE.Vector3(3.00, 1.25, 0.92), r: 1.45 },
    { c: new THREE.Vector3(3.25, 0.65, 0.80), r: 1.35 },
    { c: new THREE.Vector3(2.35, 0.05, 0.78), r: 1.00 },
    { c: new THREE.Vector3(4.05, 0.10, 0.86), r: 1.00 },
    { c: new THREE.Vector3(3.05, -0.25, 0.76), r: 0.95 }
  ].forEach(l => {
    const I = wallIntersectionFromScenePoint(l.c);
    const m = makeWallCircleYZ(projectedRadius(l.c, l.r) * 0.55, paleGreen, 0.55);
    m.position.copy(I).add(new THREE.Vector3(0.040, 0, 0));
    panel.imageGroup.add(m);
  });

  const bottom = wallIntersectionFromScenePoint(new THREE.Vector3(3.20, -2.45, 0.80));
  const mid = wallIntersectionFromScenePoint(new THREE.Vector3(3.22, -1.25, 0.80));
  const top = wallIntersectionFromScenePoint(new THREE.Vector3(3.24, 0.08, 0.80));
  const sh = new THREE.Shape();
  sh.moveTo(bottom.z - 0.17, bottom.y);
  sh.lineTo(mid.z - 0.10, mid.y);
  sh.lineTo(top.z - 0.055, top.y);
  sh.lineTo(top.z + 0.065, top.y);
  sh.lineTo(mid.z + 0.105, mid.y);
  sh.lineTo(bottom.z + 0.19, bottom.y);
  sh.closePath();
  const trunkImg = new THREE.Mesh(
    new THREE.ShapeGeometry(sh),
    mat(paleBrown, { opacity: 0.58, side: THREE.DoubleSide, depthWrite: false })
  );
  trunkImg.rotation.y = Math.PI / 2;
  trunkImg.position.x = wallX + 0.055;
  panel.imageGroup.add(trunkImg);

  const branchCenter = wallIntersectionFromScenePoint(new THREE.Vector3(3.22, -0.20, 0.80)).setX(wallX + 0.06);
  const branchL = wallIntersectionFromScenePoint(new THREE.Vector3(2.35, 0.48, 0.80)).setX(wallX + 0.06);
  const branchR = wallIntersectionFromScenePoint(new THREE.Vector3(4.05, 0.55, 0.84)).setX(wallX + 0.06);
  panel.imageGroup.add(cylinderBetween(branchCenter, branchL, 0.038, paleBrown, 0.58));
  panel.imageGroup.add(cylinderBetween(branchCenter, branchR, 0.038, paleBrown, 0.58));
}

function makePanel(kind) {
  const root = new THREE.Group();
  root.add(makeWall());
  root.add(makeTree());

  const sampleGroup = new THREE.Group();
  root.add(sampleGroup);
  wallTargets.forEach((W, i) => {
    const ring = makeWallRingYZ(i === selectedWallIndex ? 0.125 : 0.095, i === selectedWallIndex ? 0xff0000 : 0xffcc00);
    ring.position.copy(W).add(new THREE.Vector3(0.065, 0, 0));
    registerInteractive(ring, {
      title: `Wall point ${i + 1}`,
      tooltip: 'Click to select this wall point',
      body: 'This point shows how many directions arrive without a pinhole, but only one matching ray survives through the aperture.',
      onClick: () => {
        selectedWallIndex = i;
        rebuildPanels();
        updateState(false);
      }
    });
    sampleGroup.add(ring);
  });

  const imageGroup = new THREE.Group();
  const rejectedGroup = new THREE.Group();
  const rayGroup = new THREE.Group();
  const focusGroup = new THREE.Group();
  const barrierGroup = makeBarrier();
  const pinholeMesh = makeWallCircleYZ(0.13, 0xffffff, 1);
  pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.105, 0, 0));
  registerInteractive(pinholeMesh, {
    title: 'Pinhole aperture',
    tooltip: 'Drag the pinhole',
    body: 'Moving the aperture changes the straight-line paths and shifts the inverted wall projection.'
  });

  root.add(imageGroup, rejectedGroup, rayGroup, focusGroup, barrierGroup, pinholeMesh);

  const panel = { root, kind, sampleGroup, imageGroup, rejectedGroup, rayGroup, focusGroup, barrierGroup, pinholeMesh };
  updatePanelKind(panel, kind);
  return panel;
}

function updatePanelKind(panel, kind) {
  panel.kind = kind;
  clearGroup(panel.imageGroup);
  clearGroup(panel.rejectedGroup);
  clearGroup(panel.rayGroup);
  clearGroup(panel.focusGroup);

  const isPin = kind === 'pin';
  panel.barrierGroup.visible = isPin;
  panel.pinholeMesh.visible = isPin;
  panel.imageGroup.visible = isPin;
  panel.rejectedGroup.visible = isPin;

  if (isPin) {
    addProjectedImage(panel);
    addPinholeRays(panel);
  } else {
    addNoApertureRays(panel, comparisonMode);
  }

  panel.pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.105, 0, 0));
  panel.sampleGroup.children.forEach((r, i) => {
    r.geometry.dispose();
    const rr = i === selectedWallIndex ? 0.125 : 0.095;
    r.geometry = new THREE.RingGeometry(rr * 0.68, rr, 36);
    r.rotation.y = Math.PI / 2;
    r.material = mat(i === selectedWallIndex ? 0xff0000 : 0xffcc00, { side: THREE.DoubleSide });
  });
}

const activePanel = makePanel('no');
const compareLeft = makePanel('no');
const compareRight = makePanel('pin');

const activeRoot = new THREE.Group();
activeRoot.add(activePanel.root);

const compareRoot = new THREE.Group();
compareLeft.root.scale.setScalar(0.48);
compareRight.root.scale.setScalar(0.48);
compareLeft.root.position.set(-2.55, 0.02, 0);
compareRight.root.position.set(2.55, 0.02, 0);
compareRoot.add(compareLeft.root, compareRight.root);

function rebuildPanels() {
  updatePanelKind(activePanel, apertureMode === 'No opening (a)' ? 'no' : 'pin');
  updatePanelKind(compareLeft, 'no');
  updatePanelKind(compareRight, 'pin');
}

function syncSceneRoots() {
  if (comparisonMode) {
    if (activeRoot.parent) scene.remove(activeRoot);
    if (!compareRoot.parent) scene.add(compareRoot);
  } else {
    if (compareRoot.parent) scene.remove(compareRoot);
    if (!activeRoot.parent) scene.add(activeRoot);
  }
}

rebuildPanels();
syncSceneRoots();
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.72 });

const labels = {
  activeWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '34px', color: '#000' }),
  activePin: addLabel('Pinhole', new THREE.Vector3(), { fontSize: '32px', color: '#000' }),
  activePanelA: addLabel('(a)', new THREE.Vector3(), { fontSize: '36px', color: '#000' }),
  activePanelB: addLabel('(b)', new THREE.Vector3(), { fontSize: '36px', color: '#000' }),
  leftWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '26px', color: '#000' }),
  rightWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '26px', color: '#000' }),
