function localWorld(root, x, y, z) {
  root.updateMatrixWorld(true);
  return root.localToWorld(new THREE.Vector3(x, y, z));
}

function setLabelVisible(label, visible) {
  label.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updateLabelVisibility() {
  const isPin = apertureMode === 'Pinhole opening (b)';

  setLabelVisible(labels.activeWall, !comparisonMode);
  setLabelVisible(labels.activePin, !comparisonMode && isPin);
  setLabelVisible(labels.activePanelA, !comparisonMode && !isPin);
  setLabelVisible(labels.activePanelB, !comparisonMode && isPin);

  setLabelVisible(labels.leftWall, comparisonMode);
  setLabelVisible(labels.rightWall, comparisonMode);
  setLabelVisible(labels.rightPin, comparisonMode);
  setLabelVisible(labels.leftA, comparisonMode);
