  labels.activeWall.pos.copy(localWorld(activePanel.root, wallX, 2.42, 0.10));
  labels.activePin.pos.copy(localWorld(activePanel.root, -0.35, 3.15, 1.00));
  labels.activePanelA.pos.copy(localWorld(activePanel.root, 0.25, -3.10, 0.45));
  labels.activePanelB.pos.copy(localWorld(activePanel.root, 0.35, -3.10, 0.45));

  labels.leftWall.pos.copy(localWorld(compareLeft.root, wallX, 2.42, 0.10));
  labels.rightWall.pos.copy(localWorld(compareRight.root, wallX, 2.42, 0.10));
  labels.rightPin.pos.copy(localWorld(compareRight.root, -0.35, 3.15, 1.00));
  labels.leftA.pos.copy(localWorld(compareLeft.root, 0.25, -3.10, 0.45));
  labels.rightB.pos.copy(localWorld(compareRight.root, 0.35, -3.10, 0.45));
