}

function coneArrow(tip, dir, color, opacity = 1, radius = 0.055, length = 0.17) {
  const mesh = new THREE.Mesh(
    new THREE.ConeGeometry(radius, length, 16),
    mat(color, { opacity, depthWrite: opacity >= 0.95 })
