Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="apertureState">Opening: No opening (a)</button>
<label style="flex-direction:row;align-items:center;gap:6px">
  <input id="rayComparison" type="checkbox" checked>
  Side-by-side ray comparison
</label>
<button id="resetPinhole">Reset pinhole</button>
<div id="stepTitle" style="font-weight:bold;margin-top:4px">Source-style comparison</div>
<div id="stepNarration" style="font-size:11px;line-height:1.25;max-width:320px">
  Panels (a) and (b) are shown side by side: without an aperture, each wall point receives many directions; with a pinhole, one narrow bundle forms an inverted image.
</div>
<div style="display:flex;gap:4px;margin-top:3px">
  <button id="prevStep">◀</button>
  <button id="nextStep">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// wall panel             → white BufferGeometry YZ rectangle at fixed X with thick black CylinderGeometry outline
// tree trunk             → tapered brown ShapeGeometry billboard, large and source-proportioned
// tree branches          → brown CylinderGeometry strokes over foliage
// tree canopy            → overlapping green CircleGeometry billboards
// panel (a) rays         → full multi-point green/brown CylinderGeometry ray bundles to two wall targets with ConeGeometry arrows
// barrier panel (b)      → tall black BoxGeometry pinhole screen with slight side thickness
// pinhole                → white CircleGeometry disk on screen, draggable
// panel (b) rays         → surviving S→pinhole→wall CylinderGeometry rays with source-style arrowheads
// rejected rays          → very faint grey/brown direct rays blocked by the screen
// inverted wall image    → larger translucent wall-mounted tree silhouette from projected foliage/trunk geometry
// labels                 → addLabel: Wall, Pinhole, (a), (b)

const wallX = -2.35;
const wallY0 = -2.62, wallY1 = 2.72;
const wallZ0 = 0.00, wallZ1 = 1.42;
const brown = 0x7f4a21;
const darkBrown = 0x5d3216;
const greenRay = 0x22d900;
const darkGreen = 0x179900;
const brightGreen = 0x38ff00;
const midGreen = 0x23d600;
const paleGreen = 0xaaff80;
const paleGreen2 = 0x8ee47c;
const paleBrown = 0xbda38e;

const pinhole = new THREE.Vector3(-0.36, -0.42, 0.79);
const defaultPinhole = pinhole.clone();
const wallTargets = [
  new THREE.Vector3(wallX, 0.43, 0.55),
  new THREE.Vector3(wallX, -1.92, 0.31)
];

let selectedWallIndex = 0;
let apertureMode = 'No opening (a)';
let comparisonMode = true;
let currentStep = 0;

const scenePoints = [
  { name: 'top foliage',    p: new THREE.Vector3(1.73, 1.70, 0.84), color: greenRay, type: 'leaf', r: 0.62 },
  { name: 'upper foliage',  p: new THREE.Vector3(2.05, 0.94, 0.75), color: greenRay, type: 'leaf', r: 0.70 },
  { name: 'left foliage',   p: new THREE.Vector3(1.30, 0.15, 0.70), color: greenRay, type: 'leaf', r: 0.48 },
  { name: 'right foliage',  p: new THREE.Vector3(2.58, 0.07, 0.80), color: greenRay, type: 'leaf', r: 0.50 },
  { name: 'lower foliage',  p: new THREE.Vector3(1.75, -0.57, 0.66), color: greenRay, type: 'leaf', r: 0.43 },
  { name: 'left branch',    p: new THREE.Vector3(1.46, -0.18, 0.76), color: brown, type: 'wood', r: 0.16 },
  { name: 'right branch',   p: new THREE.Vector3(2.28, -0.06, 0.80), color: brown, type: 'wood', r: 0.16 },
  { name: 'trunk middle',   p: new THREE.Vector3(1.94, -1.35, 0.73), color: brown, type: 'wood', r: 0.20 },
  { name: 'trunk bottom',   p: new THREE.Vector3(1.98, -2.20, 0.72), color: brown, type: 'wood', r: 0.18 }
];

const foliageLobes = [
  { c: [1.82, 1.33, 0.87], r: 0.92, col: darkGreen },
  { c: [2.07, 0.67, 0.76], r: 0.98, col: brightGreen },
  { c: [1.32, 0.02, 0.70], r: 0.63, col: brightGreen },
  { c: [2.58, -0.05, 0.79], r: 0.64, col: midGreen },
  { c: [1.76, -0.48, 0.67], r: 0.60, col: brightGreen }
];

const mats = new Map();
function mat(color, opts = {}) {
  const opacity = opts.opacity ?? 1;
  const side = opts.side ?? THREE.FrontSide;
  const depthWrite = opts.depthWrite ?? opacity >= 0.95;
  const key = `${color}_${opacity}_${side}_${depthWrite}`;
  if (!mats.has(key)) {
    mats.set(key, new THREE.MeshBasicMaterial({
      color,
      transparent: opacity < 1,
      opacity,
      side,
      depthWrite
    }));
  }
  return mats.get(key);
}

function cylinderBetween(a, b, radius, color, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-6);
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 10, 1),
    mat(color, { opacity, depthWrite: opacity >= 0.92 })
  );
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function coneArrow(tip, dir, color, opacity = 1, radius = 0.055, length = 0.18) {
  const mesh = new THREE.Mesh(
    new THREE.ConeGeometry(radius, length, 16),
    mat(color, { opacity, depthWrite: opacity >= 0.92 })
  );
  mesh.position.copy(tip).addScaledVector(dir.clone().normalize(), -length / 2);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return mesh;
}

function addRay(group, a, b, color, opts = {}) {
  const opacity = opts.opacity ?? 1;
  const radius = opts.radius ?? 0.011;
  group.add(cylinderBetween(a, b, radius, color, opacity));
  if (opts.arrow !== false) {
    const dir = new THREE.Vector3().subVectors(b, a).normalize();
    const t = opts.arrowT ?? 0.96;
    const tip = a.clone().lerp(b, t);
    group.add(coneArrow(tip, dir, color, opacity, opts.arrowRadius ?? 0.050, opts.arrowLength ?? 0.17));
  }
}

function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.traverse?.(o => o.geometry?.dispose?.());
  }
}

function wallIntersectionFromScenePoint(S, P = pinhole) {
  const u = (P.x - wallX) / (S.x - P.x);
  return P.clone().add(new THREE.Vector3().subVectors(P, S).multiplyScalar(u));
}

function projectedRadius(S, r, P = pinhole) {
  return r * Math.abs((P.x - wallX) / (S.x - P.x));
}

function makeCircleXY(radius, color, opacity = 1, segments = 64) {
  return new THREE.Mesh(
    new THREE.CircleGeometry(radius, segments),
    mat(color, { opacity, side: THREE.DoubleSide, depthWrite: opacity >= 0.95 })
  );
}

function makeWallCircleYZ(radius, color, opacity = 1, segments = 64) {
  const m = makeCircleXY(radius, color, opacity, segments);
  m.rotation.y = Math.PI / 2;
  return m;
}

function makeWallTargetDot(radius, color, opacity) {
  const m = makeWallCircleYZ(radius, color, opacity, 24);
  m.userData.isTargetDot = true;
  return m;
}

function makeWall() {
  const g = new THREE.Group();
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ0, wallX, wallY1, wallZ1,
    wallX, wallY0, wallZ0, wallX, wallY1, wallZ1, wallX, wallY0, wallZ1
  ]), 3));
  geom.computeVertexNormals();
  g.add(new THREE.Mesh(geom, mat(0xffffff, { side: THREE.DoubleSide })));

  [
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ0)],
    [new THREE.Vector3(wallX, wallY0, wallZ1), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY1, wallZ0), new THREE.Vector3(wallX, wallY1, wallZ1)],
    [new THREE.Vector3(wallX, wallY0, wallZ0), new THREE.Vector3(wallX, wallY0, wallZ1)]
  ].forEach(([a, b]) => g.add(cylinderBetween(a, b, 0.025, 0x000000)));
  return g;
}

function makeTree() {
  const g = new THREE.Group();

  const trunkShape = new THREE.Shape();
  trunkShape.moveTo(1.50, -2.55);
  trunkShape.bezierCurveTo(1.66, -2.40, 1.73, -1.65, 1.76, -0.55);
  trunkShape.lineTo(1.80, 0.11);
  trunkShape.lineTo(2.05, 0.11);
  trunkShape.bezierCurveTo(2.00, -0.68, 2.10, -1.58, 2.25, -2.55);
  trunkShape.bezierCurveTo(2.08, -2.64, 1.67, -2.64, 1.50, -2.55);
  const trunk = new THREE.Mesh(new THREE.ShapeGeometry(trunkShape), mat(brown, { side: THREE.DoubleSide }));
  trunk.position.z = 0.72;
  g.add(trunk);

  foliageLobes.forEach(l => {
    const m = makeCircleXY(l.r, l.col);
    m.position.set(l.c[0], l.c[1], l.c[2]);
    g.add(m);
  });

  [
    [new THREE.Vector3(1.88, -0.16, 0.73), new THREE.Vector3(1.22, 0.42, 0.76), 0.046],
    [new THREE.Vector3(1.92, -0.04, 0.73), new THREE.Vector3(2.45, 0.48, 0.80), 0.049],
    [new THREE.Vector3(1.80, -0.73, 0.73), new THREE.Vector3(1.32, -0.18, 0.75), 0.036],
    [new THREE.Vector3(2.02, -0.66, 0.73), new THREE.Vector3(2.56, -0.12, 0.79), 0.036]
  ].forEach(([a, b, r]) => g.add(cylinderBetween(a, b, r, brown)));

  return g;
}

function makeBarrier() {
  const g = new THREE.Group();
  const slab = new THREE.Mesh(new THREE.BoxGeometry(0.16, 5.18, 1.30), mat(0x000000));
  slab.position.set(-0.36, 0.02, 0.82);
  g.add(slab);
  const side = new THREE.Mesh(new THREE.BoxGeometry(0.035, 5.18, 0.05), mat(0x161616));
  side.position.set(-0.455, 0.02, 1.49);
  g.add(side);
  return g;
}

function nearestProjectedScenePoint(W) {
  let best = null, bestD = Infinity;
  scenePoints.forEach(sp => {
    const I = wallIntersectionFromScenePoint(sp.p);
    const d2 = (I.y - W.y) ** 2 + (I.z - W.z) ** 2;
    if (d2 < bestD) {
      bestD = d2;
      best = sp;
    }
  });
  return best;
}

function addNoApertureRays(panel, onlySelected = false) {
  const targets = onlySelected ? [wallTargets[selectedWallIndex]] : wallTargets;
  targets.forEach((W, wi) => {
    scenePoints.forEach((sp, idx) => {
      const a = sp.p.clone();
      const b = W.clone();
      a.z += (idx - 4) * 0.006;
      b.y += onlySelected ? 0 : (idx - 4) * 0.010;
      b.z += onlySelected ? 0 : (wi === 0 ? 0.007 : -0.006) * (idx - 4);
      addRay(panel.rayGroup, a, b, sp.color, {
        radius: sp.type === 'wood' ? 0.012 : 0.011,
        arrowRadius: sp.type === 'wood' ? 0.060 : 0.052,
        arrowLength: 0.18,
        arrowT: 0.965
      });
    });
  });
}

function addPinholeRays(panel) {
  scenePoints.forEach((sp, idx) => {
    const I = wallIntersectionFromScenePoint(sp.p);
    const c = sp.color;
    addRay(panel.rayGroup, sp.p, pinhole, c, {
      radius: 0.010,
      arrow: false,
      opacity: 0.95
    });
    addRay(panel.rayGroup, pinhole, I, c, {
      radius: 0.012,
      arrowRadius: sp.type === 'wood' ? 0.058 : 0.052,
      arrowLength: 0.17,
      arrowT: 0.945,
      opacity: 0.98
    });

    if (idx % 2 === 0) {
      const blockedTarget = wallTargets[idx % wallTargets.length];
      addRay(panel.rejectedGroup, sp.p, blockedTarget, sp.type === 'leaf' ? 0x7fcf70 : 0x6a6a6a, {
        opacity: 0.13,
        radius: 0.006,
        arrow: false
      });
    }
  });

  const W = wallTargets[selectedWallIndex];
  const match = nearestProjectedScenePoint(W);
  if (match) {
    const I = wallIntersectionFromScenePoint(match.p);
    addRay(panel.focusGroup, match.p, pinhole, match.color, { radius: 0.017, arrow: false });
    addRay(panel.focusGroup, pinhole, I, match.color, {
      radius: 0.017,
      arrowRadius: 0.068,
      arrowLength: 0.19,
      arrowT: 0.948
    });
  }
}

function addProjectedImage(panel) {
  foliageLobes.forEach((l, i) => {
    const C = new THREE.Vector3(l.c[0], l.c[1], l.c[2]);
    const I = wallIntersectionFromScenePoint(C);
    const radius = projectedRadius(C, l.r) * 1.02;
    const m = makeWallCircleYZ(radius, i === 0 ? paleGreen2 : paleGreen, 0.72, 64);
    m.position.copy(I).add(new THREE.Vector3(0.055 + i * 0.002, 0, 0));
    panel.imageGroup.add(m);
  });

  const bottom = wallIntersectionFromScenePoint(new THREE.Vector3(1.88, -2.42, 0.72));
  const mid = wallIntersectionFromScenePoint(new THREE.Vector3(1.88, -1.18, 0.72));
  const top = wallIntersectionFromScenePoint(new THREE.Vector3(1.90, 0.05, 0.72));
  const sh = new THREE.Shape();
  sh.moveTo(bottom.z - 0.17, bottom.y);
  sh.bezierCurveTo(mid.z - 0.12, mid.y - 0.10, top.z - 0.06, top.y - 0.03, top.z - 0.05, top.y);
  sh.lineTo(top.z + 0.07, top.y);
  sh.bezierCurveTo(mid.z + 0.12, mid.y - 0.08, bottom.z + 0.19, bottom.y, bottom.z + 0.19, bottom.y);
  sh.closePath();
  const trunkImg = new THREE.Mesh(
    new THREE.ShapeGeometry(sh),
    mat(paleBrown, { opacity: 0.70, side: THREE.DoubleSide, depthWrite: false })
  );
  trunkImg.rotation.y = Math.PI / 2;
  trunkImg.position.x = wallX + 0.070;
  panel.imageGroup.add(trunkImg);

  const branchCenter = wallIntersectionFromScenePoint(new THREE.Vector3(1.90, -0.16, 0.73)).setX(wallX + 0.075);
  const branchL = wallIntersectionFromScenePoint(new THREE.Vector3(1.25, 0.42, 0.76)).setX(wallX + 0.075);
  const branchR = wallIntersectionFromScenePoint(new THREE.Vector3(2.48, 0.45, 0.80)).setX(wallX + 0.075);
  panel.imageGroup.add(cylinderBetween(branchCenter, branchL, 0.027, paleBrown, 0.70));
  panel.imageGroup.add(cylinderBetween(branchCenter, branchR, 0.027, paleBrown, 0.70));
}

function makePanel(kind) {
  const root = new THREE.Group();
  root.add(makeWall());

  const imageGroup = new THREE.Group();
  const rejectedGroup = new THREE.Group();
  const rayGroup = new THREE.Group();
  const focusGroup = new THREE.Group();
  const barrierGroup = makeBarrier();
  const treeGroup = makeTree();

  const sampleGroup = new THREE.Group();
  wallTargets.forEach((W, i) => {
    const dot = makeWallTargetDot(i === selectedWallIndex ? 0.038 : 0.030, i === selectedWallIndex ? 0xcc0000 : 0xd6ad00, 0.28);
    dot.position.copy(W).add(new THREE.Vector3(0.060, 0, 0));
    registerInteractive(dot, {
      title: `Wall point ${i + 1}`,
      tooltip: 'Click to select this wall point',
      body: 'The faint wall point selects one target location while the main diagram remains source-style: rays, not colored rings, show what reaches the wall.',
      onClick: () => {
        selectedWallIndex = i;
        rebuildPanels();
        updateState(false);
      }
    });
    sampleGroup.add(dot);

    const hit = makeWallTargetDot(0.16, 0xffffff, 0.001);
    hit.position.copy(W).add(new THREE.Vector3(0.075, 0, 0));
    registerInteractive(hit, {
      title: `Wall point ${i + 1}`,
      tooltip: 'Click to select this wall point',
      body: 'A wall point without a pinhole receives many rays; the pinhole restricts it to the ray that lines up with the aperture.',
      onClick: () => {
        selectedWallIndex = i;
        rebuildPanels();
        updateState(false);
      }
    });
    sampleGroup.add(hit);
  });

  const pinholeMesh = makeWallCircleYZ(0.115, 0xffffff, 1);
  pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.090, 0, 0));
  registerInteractive(pinholeMesh, {
    title: 'Pinhole aperture',
    tooltip: 'Drag the pinhole',
    body: 'The small opening admits only straight rays passing through it. Drag it to shift the inverted projection on the wall.'
  });

  root.add(imageGroup, rejectedGroup, rayGroup, focusGroup, barrierGroup, pinholeMesh, treeGroup, sampleGroup);

  const panel = { root, kind, imageGroup, rejectedGroup, rayGroup, focusGroup, barrierGroup, pinholeMesh, sampleGroup };
  updatePanelKind(panel, kind);
  return panel;
}

function updatePanelKind(panel, kind) {
  panel.kind = kind;
  clearGroup(panel.imageGroup);
  clearGroup(panel.rejectedGroup);
  clearGroup(panel.rayGroup);
  clearGroup(panel.focusGroup);

  const isPin = kind === 'pin';
  panel.barrierGroup.visible = isPin;
  panel.pinholeMesh.visible = isPin;
  panel.imageGroup.visible = isPin;
  panel.rejectedGroup.visible = isPin;

  if (isPin) {
    addProjectedImage(panel);
    addPinholeRays(panel);
  } else {
    addNoApertureRays(panel, false);
  }

  panel.pinholeMesh.position.copy(pinhole).add(new THREE.Vector3(-0.090, 0, 0));
  panel.sampleGroup.children.forEach((dot, i) => {
    if (!dot.userData.isTargetDot) return;
    const targetIndex = Math.floor(i / 2);
    dot.geometry.dispose();
    dot.geometry = new THREE.CircleGeometry(targetIndex === selectedWallIndex ? 0.038 : 0.030, 24);
    dot.rotation.y = Math.PI / 2;
    dot.material = mat(targetIndex === selectedWallIndex ? 0xcc0000 : 0xd6ad00, {
      opacity: targetIndex === selectedWallIndex ? 0.30 : 0.18,
      side: THREE.DoubleSide,
      depthWrite: false
    });
  });
}

const activePanel = makePanel('no');
const compareLeft = makePanel('no');
const compareRight = makePanel('pin');

const activeRoot = new THREE.Group();
activePanel.root.scale.setScalar(1.00);
activeRoot.add(activePanel.root);

const compareRoot = new THREE.Group();
compareLeft.root.scale.setScalar(0.74);
compareRight.root.scale.setScalar(0.74);
compareLeft.root.position.set(-2.08, 0.02, 0);
compareRight.root.position.set(2.08, 0.02, 0);
compareRoot.add(compareLeft.root, compareRight.root);

function rebuildPanels() {
  updatePanelKind(activePanel, apertureMode === 'No opening (a)' ? 'no' : 'pin');
  updatePanelKind(compareLeft, 'no');
  updatePanelKind(compareRight, 'pin');
}

function syncSceneRoots() {
  if (comparisonMode) {
    if (activeRoot.parent) scene.remove(activeRoot);
    if (!compareRoot.parent) scene.add(compareRoot);
  } else {
    if (compareRoot.parent) scene.remove(compareRoot);
    if (!activeRoot.parent) scene.add(activeRoot);
  }
}

rebuildPanels();
syncSceneRoots();

function refit() {
  setCameraView({
    projection: 'oblique',
    obliqueAngleDeg: 45,
    depthScale: 0.5,
    rollDeg: 0,
    heightFraction: comparisonMode ? 0.92 : 0.88,
    distanceScale: 1.05
  });
}

refit();

const labels = {
  activeWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '35px', color: '#000' }),
  activePin: addLabel('Pinhole', new THREE.Vector3(), { fontSize: '34px', color: '#000' }),
  activePanelA: addLabel('(a)', new THREE.Vector3(), { fontSize: '38px', color: '#000' }),
  activePanelB: addLabel('(b)', new THREE.Vector3(), { fontSize: '38px', color: '#000' }),
  leftWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '27px', color: '#000' }),
  rightWall: addLabel('Wall', new THREE.Vector3(), { fontSize: '27px', color: '#000' }),
  rightPin: addLabel('Pinhole', new THREE.Vector3(), { fontSize: '27px', color: '#000' }),
  leftA: addLabel('(a)', new THREE.Vector3(), { fontSize: '34px', color: '#000' }),
  rightB: addLabel('(b)', new THREE.Vector3(), { fontSize: '34px', color: '#000' })
};

Object.values(labels).forEach(l => {
  l.div.style.fontFamily = 'Georgia, Times New Roman, serif';
});

function localWorld(root, x, y, z) {
  root.updateMatrixWorld(true);
  return root.localToWorld(new THREE.Vector3(x, y, z));
}

function setLabelVisible(label, visible) {
  label.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updateLabelVisibility() {
  const isPin = apertureMode === 'Pinhole opening (b)';

  setLabelVisible(labels.activeWall, !comparisonMode);
  setLabelVisible(labels.activePin, !comparisonMode && isPin);
  setLabelVisible(labels.activePanelA, !comparisonMode && !isPin);
  setLabelVisible(labels.activePanelB, !comparisonMode && isPin);

  setLabelVisible(labels.leftWall, comparisonMode);
  setLabelVisible(labels.rightWall, comparisonMode);
  setLabelVisible(labels.rightPin, comparisonMode);
  setLabelVisible(labels.leftA, comparisonMode);
  setLabelVisible(labels.rightB, comparisonMode);

  labels.activeWall.pos.copy(localWorld(activePanel.root, wallX + 0.02, 2.25, 0.04));
  labels.activePin.pos.copy(localWorld(activePanel.root, -0.40, 2.72, 0.92));
  labels.activePanelA.pos.copy(localWorld(activePanel.root, -0.15, -2.42, 0.35));
  labels.activePanelB.pos.copy(localWorld(activePanel.root, -0.06, -2.42, 0.35));

  labels.leftWall.pos.copy(localWorld(compareLeft.root, wallX + 0.02, 2.25, 0.04));
  labels.rightWall.pos.copy(localWorld(compareRight.root, wallX + 0.02, 2.25, 0.04));
  labels.rightPin.pos.copy(localWorld(compareRight.root, -0.38, 2.72, 0.92));
  labels.leftA.pos.copy(localWorld(compareLeft.root, -0.15, -2.42, 0.35));
  labels.rightB.pos.copy(localWorld(compareRight.root, -0.06, -2.42, 0.35));
}

function updateState(doRefit = true) {
  comparisonMode = document.getElementById('rayComparison').checked;
  syncSceneRoots();
  rebuildPanels();

  document.getElementById('apertureState').textContent = `Opening: ${apertureMode}`;
  updateLabelVisibility();

  if (doRefit) refit();
}

document.getElementById('apertureState').addEventListener('click', () => {
  apertureMode = apertureMode === 'No opening (a)' ? 'Pinhole opening (b)' : 'No opening (a)';
  updateState(!comparisonMode);
});

document.getElementById('rayComparison').addEventListener('change', () => {
  updateState(true);
});

document.getElementById('resetPinhole').addEventListener('click', () => {
  pinhole.copy(defaultPinhole);
  rebuildPanels();
  updateLabelVisibility();
});

const steps = [
  {
    title: 'No opening: no image',
    narration: 'Panel (a) shows the full source-style pattern: rays from many different tree points reach the same wall targets, so the wall receives a mixture rather than a picture.',
    state: { apertureState: 'No opening (a)', rayComparison: false }
  },
  {
    title: 'Add the pinhole',
    narration: 'The black screen blocks most directions. Only rays passing through the small aperture survive, mapping the tree onto the wall as an inverted image.',
    state: { apertureState: 'Pinhole opening (b)', rayComparison: false }
  },
  {
    title: 'Side-by-side comparison',
    narration: 'The default view keeps both complete panels visible: (a) many wall-bound ray bundles without an opening; (b) filtered pinhole rays and the larger inverted wall image.',
    state: { apertureState: 'Pinhole opening (b)', rayComparison: true }
  }
];

function goToStep(i) {
  currentStep = (i + steps.length) % steps.length;
  const s = steps[currentStep];
  apertureMode = s.state.apertureState;
  document.getElementById('rayComparison').checked = s.state.rayComparison;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarration').textContent = s.narration;
  updateState(true);
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(currentStep + 1));

let draggingPinhole = false;
let lastDrag = new THREE.Vector2();
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();

function pointerNDC(e) {
  const r = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPointer.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', e => {
  const canDrag = comparisonMode || apertureMode === 'Pinhole opening (b)';
  if (!canDrag) return;

  pointerNDC(e);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const objects = comparisonMode ? [compareRight.pinholeMesh] : [activePanel.pinholeMesh];
  const hits = dragRaycaster.intersectObjects(objects, true);
  if (!hits.length) return;

  draggingPinhole = true;
  controls.enabled = false;
  lastDrag.set(e.clientX, e.clientY);
  canvas.setPointerCapture?.(e.pointerId);
  showTooltip('Drag the aperture on the black screen', e);
});

canvas.addEventListener('pointermove', e => {
  if (!draggingPinhole) return;

  const dx = e.clientX - lastDrag.x;
  const dy = e.clientY - lastDrag.y;
  lastDrag.set(e.clientX, e.clientY);

  const scale = 1 / Math.max(camera.zoom || 1, 0.2);
  pinhole.y = THREE.MathUtils.clamp(pinhole.y - dy * 0.0085 * scale, -2.15, 2.32);
  pinhole.z = THREE.MathUtils.clamp(pinhole.z + dx * 0.0075 * scale, 0.20, 1.28);

  rebuildPanels();
  updateLabelVisibility();
  showTooltip('Moving the pinhole shifts the surviving rays and inverted wall image', e);
});

window.addEventListener('pointerup', e => {
  if (!draggingPinhole) return;
  draggingPinhole = false;
  controls.enabled = true;
  canvas.releasePointerCapture?.(e.pointerId);
  hideTooltip();
});

document.getElementById('stepTitle').textContent = 'Source-style comparison';
document.getElementById('stepNarration').textContent = 'Both panels are complete by default. Panel (a) shows both wall-target ray bundles; panel (b) shows the pinhole screen, filtered rays, and a larger inverted wall image.';
updateState(false);
// @FIGURE_CODE_END

